// FetchResource is one of the concrete resources returned by Client.Fetch.
type FetchResource interface{ isFetchResource() }

func (*InstagramProfile) isFetchResource()   {}
func (*InstagramPost) isFetchResource()      {}
func (*InstagramStory) isFetchResource()     {}
func (*InstagramHighlight) isFetchResource() {}
func (*TikTokProfile) isFetchResource()      {}
func (*TikTokPost) isFetchResource()         {}
func (*TwitterProfile) isFetchResource()     {}
func (*TwitterPost) isFetchResource()        {}
func (*RedditProfile) isFetchResource()      {}
func (*RedditPost) isFetchResource()         {}
func (*RedditSubreddit) isFetchResource()    {}

// FetchResponse is the polymorphic response returned by Client.Fetch.
type FetchResponse struct {
	ResponseMetadata
	Data FetchResource `json:"-"`
}

func (r *FetchResponse) UnmarshalJSON(data []byte) error {
	var wire struct {
		ResponseMetadata
		Data json.RawMessage `json:"data"`
	}
	if err := json.Unmarshal(data, &wire); err != nil {
		return err
	}
	r.ResponseMetadata = wire.ResponseMetadata
	var target FetchResource
	switch {
	case wire.Platform == PlatformInstagram && wire.Resource == Resource("profile"):
		target = &InstagramProfile{}
	case wire.Platform == PlatformInstagram && wire.Resource == Resource("post"):
		target = &InstagramPost{}
	case wire.Platform == PlatformInstagram && wire.Resource == Resource("entity"):
		var probe map[string]json.RawMessage
		if err := json.Unmarshal(wire.Data, &probe); err != nil {
			return err
		}
		if _, ok := probe["items"]; ok {
			target = &InstagramHighlight{}
		} else {
			target = &InstagramStory{}
		}
	case wire.Platform == PlatformTikTok && wire.Resource == Resource("profile"):
		target = &TikTokProfile{}
	case wire.Platform == PlatformTikTok && wire.Resource == Resource("post"):
		target = &TikTokPost{}
	case wire.Platform == PlatformTwitter && wire.Resource == Resource("profile"):
		target = &TwitterProfile{}
	case wire.Platform == PlatformTwitter && wire.Resource == Resource("post"):
		target = &TwitterPost{}
	case wire.Platform == PlatformReddit && wire.Resource == Resource("profile"):
		target = &RedditProfile{}
	case wire.Platform == PlatformReddit && wire.Resource == Resource("post"):
		target = &RedditPost{}
	case wire.Platform == PlatformReddit && wire.Resource == Resource("subreddit"):
		target = &RedditSubreddit{}
	default:
		return errors.New("openhandle: unsupported fetch response variant")
	}
	if err := json.Unmarshal(wire.Data, target); err != nil {
		return err
	}
	r.Data = target
	return nil
}
